//! `cli/internal/completions/zsh` witnesses for
//! `packages/effect/test/cli/completions/completions.test.ts` (Zsh section).
//!
//! The oracle is the pin itself: each fixture's script was generated by the
//! upstream `zsh.ts` and committed under `fixtures/completions/zsh/`, so the
//! byte-equality test below is stricter than the pin's `assert.include` rows.
//! Each `#[test]` names the upstream line it proves.

mod completions_fixtures;

use completions_fixtures::{
    choices, optionaldir, paths, server, simple, tricky, zsh_goldens,
};
use elm_effect_unstable::cli_completions::zsh;

/// The pin's own generator output, byte for byte. This subsumes the
/// `assert.include` rows below; the per-row tests stay for ledger traceability.
#[test]
fn zsh_script_matches_pin_goldens_byte_for_byte() {
    for (fixture, executable, descriptor, golden) in zsh_goldens() {
        assert_eq!(
            zsh::generate(executable, &descriptor()),
            golden,
            "zsh script for fixture `{fixture}` diverged from the pin"
        );
    }
}

// ---------------------------------------------------------------------------
// Rows from `completions.test.ts`, Zsh section.
// ---------------------------------------------------------------------------

#[test]
fn generates_arguments_specs_for_flags() {
    // :391
    let script = zsh::generate("greet", &simple());
    assert!(script.contains("_arguments"));
    assert!(script.contains("--loud"));
    assert!(script.contains("--times"));
}

