#[test]
fn escapes_choice_values_for_both_the_spec_quoting_and_the_action_list_re_parse() {
    // :458
    let script = zsh::generate("deploy", &tricky());
    let flag_line: Vec<&str> = script
        .lines()
        .filter(|line| line.contains(":value:("))
        .map(|line| line.trim())
        .collect();
    assert_eq!(
        flag_line.join("\n"),
        r#"'(--mode)--mode[Deploy mode]:value:(it\'\''s-fine node\:20 with\ space \(whoami\) \#tag \$HOME back\\slash say\"hi\" a\*b a\;b \~x foo\'\'' a\!b \🚀)'"#
    );
    let arg_line: Vec<&str> = script
        .lines()
        .filter(|line| line.contains("Deployment target"))
        .map(|line| line.trim())
        .collect();
    assert_eq!(
        arg_line.join("\n"),
        r#"':Deployment target:(o\'\''clock a\:b \{x,y\} a\😀b)'"#
    );
}

#[test]
fn uses_alternative_argument_sets_for_positional_arguments_and_subcommands() {
    // :468
    let script = zsh::generate("example", &optionaldir());
    assert!(script.contains(
        "    -\n    parent-arguments\n    ':Directory to start in:_directories'\n    -\n    subcommands\n    '1:command:->command'\n    '*::arg:->args'"
    ));
    assert!(!script.contains(
        "    ':Directory to start in:_directories'\n    '1:command:->command'"
    ));
}

#[test]
fn starts_with_compdef_directive() {
    // :489
    let script = zsh::generate("greet", &simple());
    assert!(script.starts_with("#compdef greet"));
}

#[test]
fn wraps_script_in_begin_end_markers_in_zsh() {
    // :495
    let script = zsh::generate("greet", &simple());
    assert!(script.contains("###-begin-greet-completions-###"));
    assert!(script.contains("###-end-greet-completions-###"));
}

#[test]
fn declares_state_machine_locals_for_commands_with_subcommands() {
    // :502
    let script = zsh::generate("server", &server());
    assert!(script.contains("local context state state_descr line"));
    assert!(script.contains("typeset -A opt_args"));
}

#[test]
fn does_not_declare_state_machine_locals_for_leaf_commands() {
    // :509
    let script = zsh::generate("greet", &simple());
    assert!(!script.contains("local context state state_descr line"));
    assert!(!script.contains("typeset -A opt_args"));
    // Same invariant for a bare leaf with no specs at all (nested `action`
    // has one flag, `serve` below has none, so the body stays empty).
    let leaf = zsh::generate("example", &optionaldir());
    assert!(leaf.contains("_example_serve() {\n}"));
}

#[test]
fn uses_specs_array_instead_of_line_continuations() {
    // :516
    let script = zsh::generate("greet", &simple());
    assert!(script.contains("local -a specs"));
    assert!(script.contains("specs=("));
    assert!(script.contains("_arguments \"${specs[@]}\""));
}

#[test]
fn generates_exclusion_groups_for_flag_aliases() {
    // :524
    let script = zsh::generate("greet", &simple());
    // --loud, -l, and --no-loud share an exclusion group.
    assert!(script.contains("'(--loud -l --no-loud)--loud[Shout the greeting]'"));
    assert!(script.contains("'(--loud -l --no-loud)-l[Shout the greeting]'"));
    assert!(script.contains("'(--loud -l --no-loud)--no-loud[Disable loud]'"));
}

#[test]
fn generates_exclusion_group_for_flags_without_aliases() {
    // :533
    let script = zsh::generate("greet", &simple());
    // --times has no alias, so the exclusion group is just (--times).
    assert!(script.contains("'(--times)--times[Repeat count]:integer:'"));
}

#[test]
fn uses_disable_description_for_boolean_negation() {
    // :540
    let script = zsh::generate("greet", &simple());
    assert!(script.contains("--no-loud[Disable loud]"));
}
